// HLS generated by Windows server CUDA/NVENC. No AI inference and no remote API.
let hls = null;
let session = null;
let sequence = 0;
let lastStop = Promise.resolve();
let monitor = null;
let poorSpeedSamples = 0;
let callback = () => {};
export function onServerStreamUpdate(fn) { callback = fn; }
export function getServerStreamState() {
    return { active: Boolean(session), height: session?.height || 0,
        startAt: session?.startAt || 0 };
}
function notify(status, speed = null) {
    callback({ status, speed, height: session?.height || 0, active: Boolean(session) });
}
function stopInternals() {
    clearInterval(monitor);
    monitor = null;
    poorSpeedSamples = 0;
    if (hls) { hls.destroy(); hls = null; }
}
export function stopServerStream() {
    ++sequence;
    stopInternals();
    const old = session;
    session = null;
    if (old) {
        const previous = lastStop;
        lastStop = previous.catch(() => {}).then(() =>
            fetch('/api/upscale/sessions/' + old.id,
                { method: 'DELETE', keepalive: true }).catch(() => {})
        );
    }
    return lastStop;
}
async function requestStream(path, height, interpolation, startAt) {
    const res = await fetch('/api/upscale/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path, height, interpolation, start_at: startAt })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Máy chủ không tạo được luồng GPU');
    return data;
}
function connectHls(video, url) {
    if (window.Hls?.isSupported()) {
        hls = new window.Hls({ maxBufferLength: 18, liveSyncDurationCount: 2 });
        hls.on(window.Hls.Events.ERROR, (_event, info) => {
            if (info.fatal) notify('Lỗi tải HLS: ' + info.details);
        });
        video.removeAttribute('src');
        video.load();
        hls.loadSource(url);
        hls.attachMedia(video);
        hls.on(window.Hls.Events.MANIFEST_PARSED, () => { video.play().catch(() => notify('Nhấn Play để bắt đầu phát HLS')); });
    } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
        video.src = url;
        video.play().catch(() => {});
    } else {
        throw new Error('Trình duyệt không hỗ trợ HLS (hls.js/MediaSource)');
    }
}
async function attachStream(path, height, interpolation, startAt, video, auto = true) {
    const token = ++sequence;
    const data = await requestStream(path, height, interpolation, startAt);
    if (token !== sequence) {
        void fetch('/api/upscale/sessions/' + data.session_id, { method: 'DELETE' });
        return;
    }
    session = { id: data.session_id, path, height, interpolation, startAt, auto };
    try {
        connectHls(video, data.url);
        notify('Đang phát video đã xử lý trên server GTX 1050 Ti');
    } catch (error) {
        stopServerStream();
        throw error;
    }
    monitor = setInterval(() => { void samplePerformance(video); }, 5000);
}
async function samplePerformance(video) {
    if (!session || video.paused) return;
    const current = session;
    try {
        const res = await fetch('/api/upscale/sessions/' + current.id + '/status');
        if (!res.ok) return;
        const data = await res.json();
        if (session !== current) return;
        if (!data.running) {
            notify('Server đã hoàn thành hoặc dừng mã hóa', data.speed);
            return;
        }
        notify('Đang mã hóa trên server', data.speed);
        poorSpeedSamples = data.speed !== null && data.speed < 0.85
            ? poorSpeedSamples + 1 : 0;
        if (current.auto && poorSpeedSamples >= 2 && current.height > 540) {
            poorSpeedSamples = 0;
            const height = current.height > 720 ? 720 : 540;
            const resumeAt = current.startAt + (Number(video.currentTime) || 0);
            notify('Server quá tải; đang hạ về ' + height + 'p', data.speed);
            stopServerStream();
            await attachStream(current.path, height, current.interpolation, resumeAt, video, current.auto);
        }
    } catch (error) {
        console.warn('[Server HLS status]', error);
    }
}
export async function startServerStream(path, opts, video) {
    const pendingStop = stopServerStream();
    const requestToken = sequence;
    await pendingStop;
    if (requestToken !== sequence) return;
    const supported = window.Hls?.isSupported() ||
        Boolean(video.canPlayType('application/vnd.apple.mpegurl'));
    if (!supported) throw new Error('Thiếu hỗ trợ HLS trên trình duyệt này');
    const interpolation = opts.preset === 'balanced' ? 'bicubic' : 'lanczos';
    const height = [540, 720, 1080].filter(value => value <= opts.cap).pop() || 540;
    await attachStream(path, height, interpolation, Number(opts.startAt) || 0, video, opts.auto !== false);
}
